examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    MonarchBreadcrumb([
        MonarchBreadcrumbItem({{parent}}),
        MonarchBreadcrumbItem({{title}}, isLinked: false),
    ]) { _ in }
    HStack(spacing: MonarchTokens.Space.space2) {
        Text({{title}}).monarchTextStyle(.title).foregroundStyle(theme.colors.textDefault)
        MonarchBadge({{status.label}}, tone: {{status.tone|tone}})
    }
    Text({{description}}).monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
    HStack(spacing: MonarchTokens.Space.space2) {
        MonarchButton({{actions.0.label}}, variant: .secondary) {}
        MonarchButton({{actions.1.label}}, variant: .primary) {}
    }
}

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    MonarchBreadcrumb([
        MonarchBreadcrumbItem("Projects"),
        MonarchBreadcrumbItem("Website refresh", isLinked: false),
    ]) { _ in }
    HStack(spacing: MonarchTokens.Space.space2) {
        Text("Website refresh").monarchTextStyle(.title).foregroundStyle(theme.colors.textDefault)
        MonarchBadge("Active", tone: .success)
    }
    Text("Tasks, owners and dates for this project.").monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
    HStack(spacing: MonarchTokens.Space.space2) {
        MonarchButton("Share", variant: .secondary) {}
        MonarchButton("New task", variant: .primary) {}
    }
}
